INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES (6006, 6, 129811, "あたしも教官の仕事を\n頑張れば、あいつに\n喜んでもらえたり\nするのかな…", 1, 11, 0, 0.3, 0, 8, 0);
