INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES (6011, 6, 129911, "マコトさん？\nどうかしましたか？\n何やら不穏な気配を\n感じ取ったのですが", 1, 11, 0, 0.8, 0, 6, 0);
